import { revalidateTag, unstable_cache } from 'next/cache'
import { getAllProducts, syncProductsFromERP, type Product } from './db'

// Cached data fetcher with 'products' tag
const getCachedProducts = unstable_cache(
  async (): Promise<Product[]> => {
    return getAllProducts()
  },
  ['catalog-products'],
  {
    tags: ['products'],
  }
)

export default async function AdminCatalogPage() {
  // Fetch products from cache (fast, doesn't re-query on every request)
  const products = await getCachedProducts()

  // Inline Server Action for syncing catalog
  async function syncCatalog() {
    'use server'

    // Trigger background sync from ERP/PIM
    // This runs asynchronously - admin can continue working immediately
    syncProductsFromERP()
      .then(() => {
        // After sync completes, invalidate the cache
        // This makes new data available across all views using the 'products' tag
        revalidateTag('products', {})
      })
      .catch((error) => {
        console.error('Sync failed:', error)
      })

    // Form submission will naturally refresh the page
    // User continues immediately while sync happens in background
  }

  const lastSync = products[0]?.lastUpdated
    ? new Date(products[0].lastUpdated).toLocaleString()
    : 'Unknown'

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <header style={{ marginBottom: '2rem' }}>
        <h1>Product Catalog</h1>
        <p style={{ color: '#666' }}>Last synced: {lastSync}</p>
      </header>

      <section style={{ marginBottom: '2rem' }}>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.75rem 1.5rem',
              backgroundColor: '#0066cc',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '1rem',
            }}
          >
            Sync Latest Catalog
          </button>
          <p style={{ fontSize: '0.875rem', color: '#666', marginTop: '0.5rem' }}>
            Triggers background sync from ERP/PIM. Page will refresh immediately while data updates in the background.
          </p>
        </form>
      </section>

      <section>
        <h2>Products ({products.length} items)</h2>
        <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '1rem' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #ddd' }}>
              <th style={{ textAlign: 'left', padding: '0.75rem' }}>SKU</th>
              <th style={{ textAlign: 'left', padding: '0.75rem' }}>Name</th>
              <th style={{ textAlign: 'right', padding: '0.75rem' }}>Price</th>
              <th style={{ textAlign: 'right', padding: '0.75rem' }}>Inventory</th>
              <th style={{ textAlign: 'center', padding: '0.75rem' }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '0.75rem', fontFamily: 'monospace', fontSize: '0.875rem' }}>
                  {product.sku}
                </td>
                <td style={{ padding: '0.75rem' }}>{product.name}</td>
                <td style={{ padding: '0.75rem', textAlign: 'right' }}>
                  ${product.price.toFixed(2)}
                </td>
                <td style={{ padding: '0.75rem', textAlign: 'right' }}>
                  {product.inventory}
                </td>
                <td style={{ padding: '0.75rem', textAlign: 'center' }}>
                  <span
                    style={{
                      display: 'inline-block',
                      padding: '0.25rem 0.75rem',
                      borderRadius: '9999px',
                      fontSize: '0.75rem',
                      fontWeight: 500,
                      backgroundColor: product.status === 'active' ? '#dcfce7' : '#fee2e2',
                      color: product.status === 'active' ? '#166534' : '#991b1b',
                    }}
                  >
                    {product.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <footer style={{ marginTop: '3rem', paddingTop: '1rem', borderTop: '1px solid #eee', fontSize: '0.875rem', color: '#666' }}>
        <p>Cache tag: "products" | Data is cached and shared across all views using this tag.</p>
      </footer>
    </div>
  )
}

